// @pit: {"label": "Commit, push, and open PR B for project helpers"}
async ({ delivery: { commit, listChangedFiles }, gh: { prCreate } }, p: { msg: string; body: string; title: string }) => {
  const files = (await listChangedFiles({ includeDeleted: true })).files;
  const c = await commit({ files, message: p.msg, push: true });
  const pr = await prCreate({ base: "main", head: "fix/project-helpers-durable", title: p.title, body: p.body });
  return { sha: (c as any).sha, pr: pr.stdout };
}
